            SaintVoice(
                "São João Crisóstomo",
                "Homilias sobre o Evangelho de São João",
                "Diante do corpo flagelado do Senhor, aprendemos a venerar Cristo também nos corpos maltratados e esquecidos que encontramos nas ruas do mundo."
