    (MysterySet.SORROWFUL to 4) to MysteryStudy(
        scriptureTitle = "A Crucificação e Morte de Jesus",
        scriptureReading = "No lugar chamado Calvário crucificam Jesus entre dois malfeitores. Ele reza pelos que o ferem: «Pai, perdoa-lhes, porque não sabem o que fazem», e acolhe o pedido do bom ladrão: «Hoje estarás comigo no paraíso». Junto à cruz estão sua mãe, outras mulheres fiéis e o discípulo amado. Vendo sua mãe e o discípulo, Jesus diz: «Mulher, eis aí o teu filho» e ao discípulo: «Eis aí a tua mãe». Depois de dizer «Tenho sede» e receber vinagre, proclama: «Tudo está consumado!», inclina a cabeça e entrega o espírito.",
        historicalContext = "A crucificação acontecia na véspera da Páscoa, exatamente nas horas em que os cordeiros pascais eram imolados no Templo de Jerusalém. O Evangelho de João sublinha que nenhum osso de Jesus foi quebrado — detalhe que o identifica ao Cordeiro Pascal de Êxodo 12,46. Quando Jesus «entrega o espírito» (paredōken to pneuma), a expressão tem duplo sentido teológico: dá seu último suspiro humano e já derrama o Espírito Santo sobre a Igreja nascente. Do lado transpassado pela lança brotam sangue e água, sinais dos sacramentos do Batismo e da Eucaristia.",
        theologicalDepth = "A Cruz não é a derrota do amor, mas sua vitória definitiva sobre o pecado e o ódio. Cristo não morreu porque Deus exigisse vingança cruel, mas porque o amor de Deus foi até o extremo para reconciliar o mundo consigo. Aos pés da Cruz nasce uma nova família espiritual: Maria torna-se Mãe dos discípulos e nós somos convidados a «acolhê-la em nossa casa» (Jo 19,27). O perdão oferecido da cruz inaugura a possibilidade real de recomeço para toda a humanidade.",
        catechismRefs = "CIC 609–623; 964; 1225; 2605",
