    ),
    (MysterySet.GLORIOUS to 2) to MysteryStudy(
        scriptureTitle = "A vinda do Espírito Santo em Pentecostes",
        scriptureReading = "Reunidos em oração no Cenáculo com Maria, mãe de Jesus, e os apóstolos, ao chegar o dia de Pentecostes ouve-se de repente um estrondo vindo do céu, como de um vento impetuoso, que enche toda a casa. Aparecem línguas como de fogo que se repartem e pousam sobre cada um deles. Todos ficam cheios do Espírito Santo e começam a proclamar as maravilhas de Deus. Pessoas de inúmeras nações, reunidas em Jerusalém, escutam com espanto cada qual em sua própria língua o anúncio do Evangelho.",
        historicalContext = "Pentecostes (Shavuot, cinquenta dias após a Páscoa) era a festa judaica das colheitas e também a memória da entrega da Lei no Monte Sinai. No Sinai houve trovão, fogo e a Lei gravada em tábuas de pedra; em Pentecostes há vento, línguas de fogo e a Nova Lei do amor gravada no coração humano (Jr 31,33). O milagre das línguas reverte a divisão da Torre de Babel (Gn 11): enquanto o orgulho humano fragmenta a comunicação, o Espírito cria comunhão sem apagar a diversidade das culturas e línguas.",
        theologicalDepth = "Pentecostes é o nascimento público da Igreja missionária. O Espírito Santo transforma discípulos trancados pelo medo em testemunhas livres e corajosas. Maria está presente no meio deles em oração — a mesma que concebeu Jesus pelo Espírito na Anunciação agora acompanha o nascimento da Igreja. O Espírito concede dons diferentes para o serviço comum e faz brotar em nós os frutos que revelam a presença de Deus: caridade, alegria, paz, paciência, bondade, mansidão e domínio próprio (Gl 5,22).",
        catechismRefs = "CIC 731–741; 767; 1830–1832",
        saintsVoices = listOf(
            SaintVoice(
                "São Cirilo de Jerusalém",
                "Catequeses sobre o Espírito Santo",
                "O Espírito chega com mansidão de amigo: ilumina a mente, aquece o coração frio e reparte a cada pessoa exatamente o dom necessário para o bem de toda a comunidade."
            ),
            SaintVoice(
                "São João Paulo II",
                "Dominum et Vivificantem",
                "A Igreja respira pelo Espírito Santo. Sem Ele, as estruturas ficam vazias e o medo fecha as portas; com Ele, o Cenáculo se abre para o mundo inteiro na força da caridade."
            ),
        ),
        symbols = listOf(
            MysterySymbol("O vento impetuoso (Ruah)", "O mesmo sopro criador de Deus em Gênesis agora renova a face da terra e abre as portas trancadas."),
            MysterySymbol("As línguas de fogo", "Fogo que não destrói, mas purifica, ilumina e dá coragem para falar a linguagem do amor."),
            MysterySymbol("Maria em oração no Cenáculo", "Modelo da Igreja orante que acolhe o Espírito em unidade e silêncio antes de partir em missão."),
        ),
        reflectionQuestions = listOf(
            "Que «portas trancadas pelo medo» existem hoje na minha vida onde preciso invocar o vento livre do Espírito?",
            "Quais frutos do Espírito (paz, paciência, bondade, mansidão) mais preciso pedir hoje para as minhas relações?",
            "Tenho usado meus dons para construir unidade na comunidade ou para competir e me isolar?"
        ),
        closingPrayer = "Vinde, Espírito Santo, abri as portas do meu medo, aquecei o que esfriou em mim e derramai em meu coração a caridade que constrói comunhão. Amém."
    ),
    (MysterySet.GLORIOUS to 3) to MysteryStudy(
        scriptureTitle = "A Assunção de Maria em corpo e alma ao Céu",
        scriptureReading = "Embora a Escritura não narre diretamente o fim da vida terrena de Maria, toda a fé da Igreja lê a sua Assunção à luz da Páscoa de Cristo e do cântico do Magnificat: «O Todo-Poderoso fez em mim maravilhas». Aquela que foi preservada do pecado e acolheu no próprio seio o Autor da Vida, terminado o curso de sua vida terrestre, foi elevada por Deus em corpo e alma à glória celeste, participando desde já da vitória plena da Ressurreição do seu Filho.",
        historicalContext = "Desde os primeiros séculos, tanto no Oriente (festa da Dormição da Mãe de Deus, Koímesis) quanto no Ocidente (Assunção), os cristãos celebram em 15 de agosto a passagem gloriosa de Maria para o Céu. Nenhuma igreja antiga jamais reivindicou possuir relíquias corporais de Maria, sinal eloquente dessa convicção apostólica. Em 1950, o Papa Pio XII definiu solenemente o dogma na constituição Munificentissimus Deus, após consultar os bispos do mundo inteiro, reconhecendo o sentido da fé do povo cristão unido ao Magistério.",
        theologicalDepth = "A Assunção não afasta Maria de nós nem a coloca acima de Cristo: ao contrário, ela é elevada pelo poder de Deus (por isso dizemos «Assunção», diferente da «Ascensão» de Jesus por força própria). Ela é o primeiro fruto pleno da Ressurreição de Jesus e o ícone do nosso próprio destino: nossa matéria, nosso corpo e nossa história inteira são chamados à glória, não ao nada. Por isso a Assunção é fonte de imensa esperança diante da velhice, da doença e da morte.",
        catechismRefs = "CIC 966; 974; 990–991",
        saintsVoices = listOf(
            SaintVoice(
                "São João Damasceno",
                "Homilias sobre a Dormição da Virgem",
                "Convinha que aquela que guardou intacta a sua entrega a Deus e carregou no seio o Criador morasse nos tabernáculos divinos, como Arca viva levada à glória do Rei."
            ),
            SaintVoice(
                "Concílio Vaticano II",
                "Lumen Gentium, 68",
                "Na glória do Céu em corpo e alma, a Mãe de Jesus já brilha para o povo de Deus peregrino na terra como sinal de segura esperança e de consolação."
            ),
        ),
        symbols = listOf(
            MysterySymbol("A Arca no Templo celeste (Ap 11,19)", "A visão do Apocalipse abre o céu e mostra a Arca da Aliança — leitura bíblica da presença gloriosa de Maria."),
            MysterySymbol("Corpo e alma glorificados", "O ser humano inteiro é querido por Deus; nossa dignidade corporal tem vocação eterna."),
            MysterySymbol("Sinal de esperança peregrina", "Onde Maria já chegou pela graça de Cristo, a Igreja inteira caminha com confiança."),
        ),
        reflectionQuestions = listOf(
            "A esperança da vida eterna ilumina minhas escolhas de hoje, ou vivo como se tudo terminasse aqui?",
            "Quando enfrento a fragilidade do corpo ou o luto por quem amo, busco consolo na promessa da Ressurreição?",
            "Como posso cultivar hoje uma união mais íntima e serena com Deus no meio da rotina?"
        ),
        closingPrayer = "Pai, que elevastes Maria à glória do Céu como primícia da nossa esperança, mantende vivo em mim o desejo da vida eterna e a união convosco. Amém."
    ),
    (MysterySet.GLORIOUS to 4) to MysteryStudy(
        scriptureTitle = "A Coroação de Maria como Rainha do Céu e da Terra",
        scriptureReading = "No livro do Apocalipse aparece um grande sinal no céu: uma mulher vestida de sol, com a lua debaixo dos pés e uma coroa de doze estrelas sobre a cabeça. Na tradição da Igreja, essa imagem luminosa reúne ao mesmo tempo o povo de Deus — a Igreja inteira — e Maria, sua filha mais bela e mãe espiritual. Associada intimamente à obra redentora de Cristo Rei, Maria recebe a coroa da glória e intercede com ternura materna por todos os seus filhos ainda a caminho.",
        historicalContext = "Na monarquia davídica do Antigo Testamento, não era a esposa do rei, mas a mãe do rei (a Gebirah, «Grande Senhora») quem ocupava um trono à direita do soberano e atuava como intercessora pelo povo — como se vê quando Salomão se levanta para acolher sua mãe Betsabeia e coloca um trono à sua direita (1Rs 2,19). A «coroa de doze estrelas» do Apocalipse representa as doze tribos de Israel e os doze apóstolos: toda a Igreja reunida em Cristo. A realeza de Maria não é poder de domínio, mas o coroamento da humilde serva que disse «Faça-se».",
        theologicalDepth = "O último mistério do Rosário encerra todo o arco da salvação mostrando que a humildade de Deus vence: aquela que se chamou «serva do Senhor» em Nazaré é coroada na glória, confirmando o Magnificat («exaltou os humildes»). Toda a realeza e intercessão de Maria são inteiramente subordinadas à única mediação de Cristo. Ao coroar o Rosário neste mistério, confiamos nossa história à ternura da Rainha da Paz e voltamos ao cotidiano levando a luz de Cristo.",
        catechismRefs = "CIC 966–972; 1138; 2677",
        saintsVoices = listOf(
            SaintVoice(
                "São Luís Maria Grignion de Montfort",
                "O Segredo Admirável do Santíssimo Rosário",
                "Cada Rosário rezado com o coração é uma coroa de rosas oferecida a Jesus e a Maria — não por vaidade de palavras, mas como gesto filial de confiança naquela que sempre nos conduz ao Filho."
            ),
            SaintVoice(
                "São João Paulo II",
                "Rosarium Virginis Mariae, 23",
                "Coroada de glória no último mistério, Maria resplandece como Rainha dos Anjos e dos Santos, antecipação e vértice da condição escatológica da Igreja."
            ),
        ),
        symbols = listOf(
            MysterySymbol("Vestida de sol", "Maria não brilha com luz própria: ela está revestida da luz de Cristo, o Sol de Justiça."),
            MysterySymbol("A coroa de doze estrelas", "Sinal da comunhão de toda a Igreja — Antiga e Nova Aliança — reunida no louvor a Deus."),
            MysterySymbol("Reinar é servir", "No Reino de Cristo, a verdadeira coroa pertence a quem amou e serviu com fidelidade até o fim."),
        ),
        reflectionQuestions = listOf(
            "Que pessoas, dores ou decisões preciso hoje confiar serenamente à intercessão materna de Maria?",
            "Tenho aprendido com Maria que a verdadeira grandeza diante de Deus é a humildade que serve?",
            "Que fruto concreto dos mistérios contemplados hoje eu quero levar comigo ao fechar este momento de oração?"
        ),
        closingPrayer = "Maria, Rainha da paz e Mãe da Igreja, apresentai ao Vosso Filho as intenções do meu coração e guiai meus passos até a alegria definitiva do Céu. Amém."
    ),
)
